head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = 'ULDSTF30207.xml';
scwin.regMode;
scwin.designTpCd;
scwin.gIsurCd;
scwin.gDtecDd;
scwin.gSeq;
scwin.gComAbbrv;
scwin.gChgTpNm;
scwin.gStrtDd;
scwin.gChgRsnNm;
scwin.gMisc;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//부모창에서 필요변수 저장
scwin.fn_GetParentValue = function() {
    scwin.gIsurCd = frame.opener.scwin.gIsurCd;
    scwin.gDtecDd = frame.opener.scwin.gDtecDd;
    scwin.gSeq = frame.opener.scwin.gSeq;
    gChgStatCd = frame.opener.gChgStatCd;
    scwin.regMode = frame.opener.scwin.regMode;
    scwin.gComAbbrv = frame.opener.scwin.gComAbbrv;
    scwin.gChgTpNm = frame.opener.scwin.gChgTpNm;
    scwin.gStrtDd = frame.opener.scwin.gStrtDd;
    scwin.gChgRsnNm = frame.opener.scwin.gChgRsnNm;
    scwin.gMisc = frame.opener.scwin.gMisc;
};


//선택한 정보 값 셋팅
scwin.fn_ReadInfo = function() {
    var url = "/ByPass.do?method=getDesignExcludeCompanyInfo" + "&ISUR_CD=" + scwin.gIsurCd + "&DTEC_DD=" + scwin.gDtecDd + "&SEQ=" + scwin.gSeq + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_MASTER.DataID = encodeURI(url);
    dts_MASTER.reset();
};



//초기화
scwin.fn_Init = function() {
    $c.stf.showObj(txb_dtec_dd, false); // 적출일자 hidden
    $c.stf.showObj(txb_isur_cd, false); // SEQ hidden
    $c.stf.showObj(txb_seq, false); // SEQ hidden

    if (scwin.regMode == "APP" && js_jobtitl == "09") {
        // 검토상태 및 사용자가 팀장일때만...
        $c.stf.showObj(btn_Approv, true); // 승인버튼
        $c.stf.showObj(btn_Resv, true); // 유보버튼

    } else {
        $c.stf.showObj(btn_Approv, false); // 승인버튼
        $c.stf.showObj(btn_Resv, false); // 유보버튼

    }

    //승인 또는 유보상태, 팀장이 로그인했을 경우 해당 문구 hidden 처리
    if (gChgStatCd == "30" || gChgStatCd == "40" || js_jobtitl == "09") {
        $c.stf.showObj(label_13, false); // 설명문

    } else {
        $c.stf.showObj(label_13, true); // 설명문

    }
    tbx_1.setValue(" " + scwin.gComAbbrv + "(" + scwin.gIsurCd + ")");
    tbx_2.setValue(" " + scwin.gChgTpNm);
    tbx_3.setValue(" " + scwin.gStrtDd.substr(0, 4) + "년 " + scwin.gStrtDd.substr(4, 2) + "월 " + scwin.gStrtDd.substr(6, 2) + "일");
    tbx_4.setValue(" " + scwin.gChgRsnNm);
    txa_misc.Text = " " + scwin.gMisc;


    // 가우스헤더 셋팅
    dts_MASTER.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BYPASS_DESIGN_EXCLUDE_SECU_INFO";
    dts_MASTER.reset();
    dts_MASTER.insertRow();
};





//승인
scwin.fn_approv = function() {
    var rtn = confirm('승인처리 하시겠습니까?');
    var vDtec_dd = $c.stf.getObjectValue(txb_dtec_dd);
    var vIsur_cd = $c.stf.getObjectValue(txb_isur_cd);
    var vSeq = $c.stf.getObjectValue(txb_seq);
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_MASTER.setCellData(1, "DTEC_DD", vDtec_dd); //적출일자
        dts_MASTER.setCellData(1, "ISUR_CD", vIsur_cd); //회사코드
        dts_MASTER.setCellData(1, "SEQ", vSeq); //SEQ
        dts_MASTER.setCellData(1, "REG_ID", js_id); //등록자ID
        dts_MASTER.setCellData(1, "PRE_REVW_EXMPT_OBJ_CHG_STAT_CD", "30"); //승인상태코드


        var url = "/ByPass.do?method=updateDesignExcludeHistReview";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_inquiry.Action = url;
        trs_inquiry.KeyName = "toinb_dataid4";
        trs_inquiry.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_inquiry.Post();
    }
};



//유보
scwin.fn_reject = function() {
    var rtn = confirm('유보처리 하시겠습니까?');
    var vDtec_dd = $c.stf.getObjectValue(txb_dtec_dd);
    var vIsur_cd = $c.stf.getObjectValue(txb_isur_cd);
    var vSeq = $c.stf.getObjectValue(txb_seq);
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_MASTER.setCellData(1, "DTEC_DD", vDtec_dd); //적출일자
        dts_MASTER.setCellData(1, "ISUR_CD", vIsur_cd); //회사코드
        dts_MASTER.setCellData(1, "SEQ", vSeq); //SEQ
        dts_MASTER.setCellData(1, "REG_ID", js_id); //등록자ID
        dts_MASTER.setCellData(1, "PRE_REVW_EXMPT_OBJ_CHG_STAT_CD", "40"); //승인상태코드

        var url = "/ByPass.do?method=updateDesignExcludeHistReview";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_inquiry.Action = url;
        trs_inquiry.KeyName = "toinb_dataid4";
        trs_inquiry.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_inquiry.Post();
    }
};
scwin.trs_inquiry_OnSuccess = async function() {
    $c.win.alert("성공적으로 처리 되었습니다.");
    await $c.frame.CloseFrame();
    // 부모창 reload 처리해야함	
    $c.frame.path("../").fn_Search();
};
scwin.trs_inquiry_OnFail = function() {
    $c.win.alert('trs_inquiry.OnFail() :' + trs_inquiry.ErrorMsg);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Approv_onclick = function() {
    scwin.fn_approv();
};
scwin.btn_Resv_onclick = function() {
    scwin.fn_reject();
};
scwin.gform_onload = function() {
    scwin.fn_GetParentValue();
    scwin.fn_Init();
    scwin.fn_ReadInfo(); //기본정보 불러오기	
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
};
